import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class UserProfileServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(UserProfileServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String userId = request.getParameter("id");
        String fields = request.getParameter("fields");

        if (userId == null || userId.isEmpty()) {
            response.sendError(400, "Missing id parameter");
            return;
        }

        // Validate userId is numeric
        if (!userId.matches("^[0-9]+$")) {
            response.sendError(400, "Invalid user ID format");
            return;
        }

        // fields parameter allows selecting which columns to return
        // Default to safe set if not specified
        String columns = "username, email, created_at";
        if (fields != null && !fields.isEmpty()) {
            // Allow caller to specify comma-separated field names
            // We check each field against allowed list
            String[] requestedFields = fields.split(",");
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < requestedFields.length; i++) {
                String field = requestedFields[i].trim();
                if (isAllowedField(field)) {
                    if (sb.length() > 0) sb.append(", ");
                    sb.append(field);
                }
            }
            if (sb.length() > 0) {
                columns = sb.toString();
            }
        }

        // Build query - userId is validated numeric, columns from allowlist
        String query = "SELECT " + columns + " FROM users WHERE user_id = " + userId;
        logger.info("Executing query for user: " + userId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            response.setContentType("application/json");
            PrintWriter out = response.getWriter();

            if (rs.next()) {
                ResultSetMetaData meta = rs.getMetaData();
                out.print("{");
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    if (i > 1) out.print(",");
                    out.print("\"" + meta.getColumnName(i) + "\":");
                    out.print("\"" + escapeJson(rs.getString(i)) + "\"");
                }
                out.print("}");
            } else {
                response.sendError(404, "User not found");
            }
        } catch (SQLException e) {
            logger.severe("Database error: " + e.getMessage());
            response.sendError(500, "Internal server error");
        }
    }

    private boolean isAllowedField(String field) {
        // Allowlist of queryable fields
        String[] allowed = {"username", "email", "created_at", "display_name",
                           "avatar_url", "bio", "location", "website",
                           "last_login", "account_status"};
        for (String a : allowed) {
            if (a.equalsIgnoreCase(field)) return true;
        }
        return false;
    }

    private String escapeJson(String value) {
        if (value == null) return "null";
        return value.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }

    // Admin search endpoint - supports flexible queries for internal tooling
    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String authHeader = request.getHeader("X-Internal-Auth");
        if (authHeader == null || !authHeader.equals(System.getenv("INTERNAL_AUTH_TOKEN"))) {
            response.sendError(403, "Forbidden");
            return;
        }

        String searchTerm = request.getParameter("q");
        String searchField = request.getParameter("field");

        if (searchTerm == null || searchField == null) {
            response.sendError(400, "Missing parameters");
            return;
        }

        // Internal admin search - constructs dynamic query
        String query = "SELECT user_id, username, email FROM users WHERE "
                     + searchField + " LIKE '%" + searchTerm + "%'";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            response.setContentType("application/json");
            PrintWriter out = response.getWriter();
            out.print("[");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.printf("{\"id\":%d,\"username\":\"%s\",\"email\":\"%s\"}",
                    rs.getInt(1), escapeJson(rs.getString(2)), escapeJson(rs.getString(3)));
                first = false;
            }
            out.print("]");
        } catch (SQLException e) {
            logger.severe("Search error: " + e.getMessage());
            response.sendError(500, "Internal server error");
        }
    }
}
